import { View, Text, SectionList, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const SECTIONS = [
  { title: "Электроник", data: ["Чихэвч", "Гар цаг"] },
  { title: "Хувцас", data: ["Гутал", "Цүнх"] },
];

function App() {
  const [selected, setSelected] = useState("");
  return (
    <View style={styles.screen}>
      <Text nativeID="chosen" style={styles.chosen}>Сонгосон: {selected || "—"}</Text>
      <SectionList
        style={styles.list}
        sections={SECTIONS}
        keyExtractor={(item, i) => item + i}
        renderSectionHeader={({ section }) => (
          <View style={styles.header}>
            <Text style={styles.headerText}>{section.title}</Text>
          </View>
        )}
        renderItem={({ item }) => (
          // энд бичнэ үү: мөрийг Pressable болгож onPress-д setSelected(item) дууд
          <View testID="row" style={styles.row}>
            <Text>{item}</Text>
          </View>
        )}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: "#f8fafc" },
  chosen: { padding: 16, fontSize: 16, fontWeight: "bold", color: "#2563eb", backgroundColor: "#eff6ff" },
  list: { flex: 1 },
  header: { padding: 12, backgroundColor: "#e0e7ff" },
  headerText: { fontSize: 16, fontWeight: "bold", color: "#3730a3" },
  row: { padding: 16, backgroundColor: "#fff" },
});

registerRootComponent(App);

import { View, Text, SectionList, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const SECTIONS = [
  { title: "Электроник", data: ["Чихэвч", "Гар цаг"] },
  { title: "Хувцас", data: ["Гутал", "Цүнх"] },
];

function App() {
  const [selected, setSelected] = useState("");
  return (
    <View style={styles.screen}>
      <Text nativeID="chosen" style={styles.chosen}>Сонгосон: {selected || "—"}</Text>
      <SectionList
        style={styles.list}
        sections={SECTIONS}
        keyExtractor={(item, i) => item + i}
        renderSectionHeader={({ section }) => (
          <View style={styles.header}>
            <Text style={styles.headerText}>{section.title}</Text>
          </View>
        )}
        renderItem={({ item }) => (
          <Pressable testID="row" style={styles.row} onPress={() => setSelected(item)}>
            <Text>{item}</Text>
          </Pressable>
        )}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: "#f8fafc" },
  chosen: { padding: 16, fontSize: 16, fontWeight: "bold", color: "#2563eb", backgroundColor: "#eff6ff" },
  list: { flex: 1 },
  header: { padding: 12, backgroundColor: "#e0e7ff" },
  headerText: { fontSize: 16, fontWeight: "bold", color: "#3730a3" },
  row: { padding: 16, backgroundColor: "#fff" },
});

registerRootComponent(App);
